        return True
    return False


def ambiguous(c: np.ndarray, margin: float = MARGIN) -> bool:
    """After stage 2: still too close to call?"""
    m = len(c)
    frac = (c > 0).sum(axis=0) / m
    if np.any(np.abs(frac - 0.5) < margin):
        return True
    med = median_floor(c[:, PERSON])
    return (c[:, PERSON] == med).sum() / m < 0.5


