"""Structural checks on results.jsonl.gz. Writes per-video summary to a json for the parquet comparison."""
import gzip
import json
import sys
from collections import defaultdict, Counter

path, out = sys.argv[1], sys.argv[2]
CLASSES = {"person", "car", "dog", "laptop", "cell phone"}
secs = defaultdict(list)
order = []          # video order of appearance (to check each video is one contiguous block)
errors = {}
problems = Counter()
examples = defaultdict(list)
keys_seen = Counter()
n = 0
bad_json = 0

def flag(kind, msg):
    problems[kind] += 1
    if len(examples[kind]) < 5:
        examples[kind].append(msg)

with gzip.open(path, "rt", encoding="utf-8") as f:
    for i, line in enumerate(f, 1):
        n += 1
        try:
            d = json.loads(line)
        except Exception:
            bad_json += 1
            flag("bad_json", f"line {i}")
            continue
        keys_seen[tuple(sorted(d))] += 1
        v = d.get("video")
        if not order or order[-1] != v:
            order.append(v)
        if "error" in d:
            errors[v] = d["error"]
            continue
        s, objs, ppl = d.get("second"), d.get("objects"), d.get("people")
        if not isinstance(s, int) or s < 0:
            flag("bad_second", f"line {i}: {s!r}")
        if not isinstance(objs, list) or not set(objs) <= CLASSES or len(set(objs)) != len(objs):
            flag("bad_objects", f"line {i}: {objs!r}")
        if not isinstance(ppl, int) or ppl < 0:
            flag("bad_people", f"line {i}: {ppl!r}")
        elif ppl >= 1 and "person" not in objs:
            flag("people_without_person", f"line {i} {v} s{s}: people={ppl} objs={objs}")
        secs[v].append(s)

videos = set(secs) | set(errors)
blocks = Counter(order)
split = [v for v, c in blocks.items() if c > 1]
for v in split:
    flag("video_split_in_file", v)

per_file = defaultdict(set)
summary = {}
for v in videos:
    fn, row = v.rsplit(":", 1)
    per_file[fn].add(int(row))
    ss = secs.get(v, [])
    c = Counter(ss)
    dup = sum(k - 1 for k in c.values() if k > 1)
    if dup:
        flag("duplicate_seconds", f"{v}: {dup}")
    if ss:
        mx = max(ss)
        if len(c) != mx + 1:
            flag("gap_in_seconds", f"{v}: {len(c)} distinct of 0..{mx}")
        if ss != sorted(ss):
            flag("unsorted_seconds", v)
    else:
        if v not in errors:
            flag("no_lines", v)
    summary[v] = {"n_secs": len(c), "max_sec": max(ss) if ss else None, "error": errors.get(v)}

for fn, rows in per_file.items():
    if rows != set(range(max(rows) + 1)):
        flag("missing_rows", f"{fn}: have {len(rows)}, max {max(rows)}")

print(f"lines {n}, bad json {bad_json}, videos {len(videos)}, files {len(per_file)}, error lines {len(errors)}")
print("line key sets:", dict(keys_seen))
print("videos per file: min", min(len(r) for r in per_file.values()), "max", max(len(r) for r in per_file.values()))
lens = sorted(s["n_secs"] for s in summary.values())
print("seconds per video: min", lens[0], "median", lens[len(lens)//2], "max", lens[-1],
      "| videos with < 5 s:", sum(l < 5 for l in lens))
print("total seconds", sum(lens), f"= {sum(lens)/3600:.1f} h")
if errors:
    print("errors:", errors)
print("problems:", dict(problems) or "none")
for k, ex in examples.items():
    print(" ", k, ex)
json.dump({"summary": summary, "rows_per_file": {k: len(v) for k, v in per_file.items()}}, open(out, "w"))

